/**
 * Typed access to the build-time GitHub snapshot.
 *
 * The JSON is generated by `scripts/sync-github.mjs` (run via `npm run
 * sync:github`) and committed. Nothing here calls the GitHub API at request
 * time, so page loads make zero GitHub requests and cannot be rate limited.
 */

import raw from "@/data/github.generated.json";

export type GitHubRepo = {
  name: string;
  description: string | null;
  url: string;
  language: string | null;
  updatedAt: string;
  createdAt: string;
  stars: number;
  forks: number;
  topics: string[];
  defaultBranch: string;
  headSha: string | null;
};

export type GitHubSnapshot = {
  syncedAt: string;
  user: string;
  profileUrl: string;
  totals: {
    publicRepos: number;
    publicWorkRepos: number;
    oldestRepo: string | null;
    lastPush: string | null;
  };
  topLanguages: { name: string; count: number }[];
  repos: GitHubRepo[];
};

export const github = raw as GitHubSnapshot;

const dateFormat = new Intl.DateTimeFormat("en-GB", {
  day: "numeric",
  month: "short",
  year: "numeric",
  timeZone: "UTC",
});

export function formatDate(iso: string | null) {
  if (!iso) return "—";
  return dateFormat.format(new Date(iso));
}

export function monthYear(iso: string | null) {
  if (!iso) return "—";
  return new Intl.DateTimeFormat("en-GB", {
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(iso));
}

export function sinceLabel(iso: string | null) {
  if (!iso) return "—";
  const start = new Date(iso).getTime();
  const months = Math.max(
    1,
    Math.round((Date.now() - start) / (1000 * 60 * 60 * 24 * 30.44)),
  );
  const years = Math.floor(months / 12);
  const rem = months % 12;
  if (years === 0) return `${months} month${months === 1 ? "" : "s"}`;
  if (rem === 0) return `${years} year${years === 1 ? "" : "s"}`;
  return `${years}y ${rem}m`;
}